H, W = len(test_input), len(test_input[0])
output = [[0 for _ in range(W)] for _ in range(H)]

# Find all non-zero points by value
points = {}
for r in range(H):
    for c in range(W):
        val = test_input[r][c]
        if val != 0:
            if val not in points:
                points[val] = []
            points[val].append((r, c))

# Process values in order (smaller first so they don't overwrite larger numbers incorrectly)
for val, pts in sorted(points.items()):
    if len(pts) == 2:
        p1, p2 = pts
        # Sort by row
        if p1[0] > p2[0]:
            p1, p2 = p2, p1

        # Vertical from p1 down to p2's row (exclusive? inclusive?)
        # Based on Demo 1: vertical stops at corner, doesn't go past
        for r in range(p1[0], p2[0]):  # stop before corner
            output[r][p1[1]] = val

        # Horizontal at p2's row from p1's col to p2's col (inclusive)
        min_c, max_c = min(p1[1], p2[1]), max(p1[1], p2[1])
        for c in range(min_c, max_c + 1):
            output[p2[0]][c] = val

    elif len(pts) == 1:
        p = pts[0]
        # Draw vertical line from this point down to bottom
        for r in range(p[0], H):
            output[r][p[1]] = val

